export default defineComponent({
  async run({ steps }) {
    const schema = steps.trigger.event.body;
    return {
      tables: schema.tables,
      relationships: schema.relationships
    };
  }
});

export default defineComponent({
  async run({ steps, $ }) {
    const diagram = steps.create_diagram.data;
    const results = [];

    for (const table of steps.parse_schema.tables) {
      const result = await $.flow.runAction('chartdb', 'add-table', {
        diagramId: diagram.id,
        tableName: table.name,
        fields: JSON.stringify(table.fields)
      });
      results.push(result);
    }

    return { tables: results };
  }
});

export default defineComponent({
  async run({ steps, $ }) {
    const diagram = steps.create_diagram.data;
    const results = [];

    for (const rel of steps.parse_schema.relationships) {
      const result = await $.flow.runAction('chartdb', 'add-relationship', {
        diagramId: diagram.id,
        sourceTableId: rel.sourceTableId,
        targetTableId: rel.targetTableId,
        sourceFieldId: rel.sourceFieldId,
        targetFieldId: rel.targetFieldId,
        type: rel.type
      });
      results.push(result);
    }

    return { relationships: results };
  }
});
